select.if:
SELECT nvl((select org_name_local from org_master where organization_id = team_organization_origin_id),' ') as team , nvl((select org_name_local from org_master where organization_id = section_code),' ') as section , nvl((select org_name_local from org_master where organization_id = task_code),' ') as task , nvl((select org_name_local from org_master where organization_id = part_group_code),' ') as part , nvl((select org_name_local from org_master where organization_id = unit_code),' ') as unit ,employee_head_count as total ,tardy_count as lateness ,early_leave_days as leaving_early ,going_out_count as outing ,sel_training_complt_count as training ,use_annual_leave_days as annual_leave ,time_and_attendance_date FROM tb_att_daily_report_s WHERE 1=1 and time_and_attendance_date = trunc(to_date(#{attDate},'DD/MM/YYYY'))
and unit_code = #{organizationId}
and part_group_code = #{organizationId}
and task_code = #{organizationId}
and section_code = #{organizationId}
and team_organization_origin_id = #{organizationId}
and department_code = #{organizationId}
and division_code = #{organizationId}
order by unit_code asc, part_group_code asc, task_code asc, section_code asc, team_organization_origin_id asc
